def apply_overrides():
    """Aplica OVERRIDES sobre RF y RNF (se llama desde build_pdf.py)."""
    for groups in (RF, RNF):
        for name, rows in groups.items():
            for i, r in enumerate(rows):
                if r[0] in OVERRIDES:
                    d, o = OVERRIDES[r[0]]
                    rows[i] = (r[0], d or r[1], r[2], o or r[3])


